import asyncioimport jsonimport osfrom aiogram import Bot, Dispatcher, typesfrom aiogram.filters import CommandStart, Commandfrom aiogram.types import MessageBOT_TOKEN = "8121698522:AAFA4wZG-Y8Mg-MyZ523hsXsYxBSsNBPlB0"CONFIG_PATH = "config.json"def load_photo_id() -> str:    if not os.path.exists(CONFIG_PATH):        return ""    try:        with open(CONFIG_PATH, "r", encoding="utf-8") as f:            return json.load(f).get("START_PHOTO_ID", "")    except Exception:        return ""def save_photo_id(file_id: str) -> None:    with open(CONFIG_PATH, "w", encoding="utf-8") as f:        json.dump({"START_PHOTO_ID": file_id}, f, ensure_ascii=False, indent=2)def display_nick(u: types.User) -> str:    """    Никнейм = отображаемое имя пользователя (Имя + Фамилия)    """    name_parts = [u.first_name, u.last_name]    full_name = " ".join(part for part in name_parts if part)    return full_name if full_name else str(u.id)async def main():    bot = Bot(token=BOT_TOKEN)    dp = Dispatcher()    START_PHOTO_ID = load_photo_id()    @dp.message(Command("setphoto"))    async def setphoto(message: Message):        nonlocal START_PHOTO_ID        # Вариант 1: /setphoto + фото в этом же сообщении        photo = message.photo[-1] if message.photo else None        # Вариант 2: /setphoto ответом на сообщение с фото        if not photo and message.reply_to_message and message.reply_to_message.photo:            photo = message.reply_to_message.photo[-1]        if not photo:            await message.answer(                "Пришли /setphoto вместе с фото (как ФОТО), или ответь /setphoto на сообщение с фото."            )            return        START_PHOTO_ID = photo.file_id        save_photo_id(START_PHOTO_ID)        await message.answer("Готово ✅ Фото сохранено и будет отправляться мгновенно.")    @dp.message(CommandStart())    async def start(message: Message):        if not START_PHOTO_ID:            await message.answer("Фото не настроено. Пришли /setphoto вместе с фото.")            return        nick = display_nick(message.from_user)        caption = (    f'✋ Привет, {nick}! '    "Наш сервис позволяет узнать, как ты записан у других людей. "    "Нажимай на кнопку ниже, и бот выдаст тебе список твоих записей.")        # Фото + текст одним сообщением — по file_id (самый быстрый способ)        await message.answer_photo(photo=START_PHOTO_ID, caption=caption)        # Потом смайлик        await message.answer("👇")    await dp.start_polling(bot)if __name__ == "__main__":    asyncio.run(main())